import os,re,json

def load_first_only():
    d=os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        print("No session dir!")
        return {}

    # Read only first part of session log
    with open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl') as f:
        lines = [l for l in f.readlines() if not l.startswith('Traceback')]
        t='\n'.join(lines)

    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        key,mtype,h,w=m[1],m.group(2),int(m[2]),int(m[3])
        end_pos = m.end()
        remaining = t[end_pos:end_pos+h]  # Just take h lines worth of chars
        grid_rows = []

        temp_count = 0
        line_start = 0
        for i, c in enumerate(remaining):
            if c == '\n':
                row_str = remaining[line_start:i].strip()
                if row_str and not row_str[0].isdigit():
                    continue
                if row_str:
                    grid_rows.append(row_str.split())
                line_start = i + 1
        grid = [[int(x) for x in row] for row in grid_rows[:h]]

        if key not in G and all(len(row)==w for row in grid):
            G[key]=grid

    return G

G=load_first_only()
